<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/purchase_step14.php';if(empty($_SESSION['po_csrf']))$_SESSION['po_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['po_csrf'];$error=null;$success=null;$suppliers=[];$products=[];$orders=[];$selected=(int)($_GET['po']??$_POST['purchase_order_id']??0);$items=[];
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'');if($action==='create'){$selected=purchase_step14_create_order($pdo,(int)$_POST['supplier_id'],(string)$_POST['order_date'],$_POST['expected_date']??null,(string)($_POST['notes']??''));$success='Purchase Order created.';}elseif($action==='add_item'){purchase_step14_add_po_item($pdo,$selected,(int)$_POST['product_id'],(float)$_POST['quantity'],($_POST['estimated_unit_cost']??'')!==''?(float)$_POST['estimated_unit_cost']:null,(string)($_POST['notes']??''));$success='PO item added.';}elseif($action==='status'){purchase_step14_set_po_status($pdo,$selected,(string)$_POST['status']);$success='PO status updated.';}}$suppliers=purchase_step14_suppliers($pdo,$orgId,true);$products=product_step11_catalog_rows($pdo,$orgId,'','ALL');$orders=purchase_step14_po_rows($pdo,$orgId);if($selected>0){$stmt=$pdo->prepare("SELECT i.*,p.product_name,p.sku FROM purchase_order_items i JOIN products p ON p.id=i.product_id WHERE i.organization_id=? AND i.purchase_order_id=? ORDER BY i.id");$stmt->execute([$orgId,$selected]);$items=$stmt->fetchAll();}}catch(Throwable $e){$error=$e->getMessage();}
function po_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function po_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Purchase Orders - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Purchase Orders</small></span></a><div class="os-top-actions"><a class="os-btn" href="supplier_center.php">Suppliers</a><a class="os-btn" href="purchase_bills.php">Bills</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a class="active" href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14B • PURCHASE ORDERS</div><h1>Plan purchases without creating stock or payable too early.</h1><p>A PO is a commitment only. Supplier liability begins from a real Bill; inventory begins from an actual Receipt.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PURCHASE ORDERS LIVE':'Review required' ?></span><span class="os-chip"><?= count($orders) ?> orders</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>PO diagnostic:</strong> <?= po_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= po_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-4"><h2>Create PO</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= po_h($csrf) ?>"><input type="hidden" name="action" value="create"><label>Supplier<select name="supplier_id" required><option value="">Choose supplier…</option><?php foreach($suppliers as $s):?><option value="<?= (int)$s['id'] ?>"><?= po_h($s['supplier_name'].' • '.$s['supplier_code']) ?></option><?php endforeach;?></select></label><label>Order Date<input type="date" name="order_date" value="<?= date('Y-m-d') ?>" required></label><label>Expected Date<input type="date" name="expected_date"></label><label>Notes<textarea name="notes" rows="3"></textarea></label><button>Create Purchase Order →</button></form><?php if($selected):?><hr><h2>Add Item to PO #<?= $selected ?></h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= po_h($csrf) ?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="purchase_order_id" value="<?= $selected ?>"><label>Product<select name="product_id" required><option value="">Choose product…</option><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"><?= po_h(($p['sku']?:'—').' • '.$p['product_name']) ?></option><?php endforeach;?></select></label><label>Quantity<input type="number" min="0.001" step="0.001" name="quantity" required></label><label>Estimated Unit Cost<input type="number" min="0" step="0.01" name="estimated_unit_cost" placeholder="Optional"></label><label>Notes<input name="notes"></label><button>Add Item →</button></form><form method="post" class="pp-form" style="margin-top:12px"><input type="hidden" name="csrf" value="<?= po_h($csrf) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="purchase_order_id" value="<?= $selected ?>"><label>PO Status<select name="status"><option value="draft">Draft</option><option value="ordered">Ordered</option><option value="closed">Closed</option><option value="cancelled">Cancelled</option></select></label><button>Update Status</button></form><?php endif;?></article><article class="os-card pp-span-8"><h2>Purchase Orders</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>PO</th><th>Supplier</th><th>Date</th><th>Expected</th><th>Items</th><th>Estimated Total</th><th>Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="?po=<?= (int)$o['id'] ?>"><b><?= po_h($o['po_number']) ?></b></a></td><td><?= po_h($o['supplier_name']) ?></td><td><?= po_h($o['order_date']) ?></td><td><?= po_h($o['expected_date']?:'—') ?></td><td><?= (int)$o['item_count'] ?></td><td><?= po_m($o['subtotal']) ?></td><td><span class="pp-badge <?= $o['status']==='cancelled'?'warn':'' ?>"><?= po_h(strtoupper($o['status'])) ?></span></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="7">No Purchase Orders yet.</td></tr><?php endif;?></tbody></table></div><?php if($selected):?><h2 style="margin-top:18px">Selected PO Items</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Stock</th><th>Product</th><th>Qty</th><th>Est. Cost</th><th>Line</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?= po_h($i['sku']) ?></td><td><?= po_h($i['product_name']) ?></td><td><?= po_h($i['ordered_quantity']) ?></td><td><?= $i['estimated_unit_cost']!==null?po_m($i['estimated_unit_cost']):'—' ?></td><td><?= po_m($i['line_amount']) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></article></section><?php endif;?><div class="os-footer-note"><strong>PO rule:</strong> creating or editing a Purchase Order never changes Inventory or Supplier Payable.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
